  private import ScalarValues::*;
  part def Controller {
    in attribute io_2 : Integer;
    attribute phase_ms : Integer := 0;
    attribute led1 : Boolean := false;
    attribute led2 : Boolean := false;
    perform action tick {
      first start;
      then assign phase_ms := phase_ms + io_2;
      then if phase_ms >= 15000 {
        first start;
        then assign phase_ms := phase_ms - 15000;
      }
      then if phase_ms >= 15000 {
        first start;
        then assign phase_ms := phase_ms - 15000;
      }
      then if phase_ms < 5000 {
        first start;
        then assign led1 := false;
        then assign led2 := false;
      }
      then if phase_ms >= 5000 and phase_ms < 10000 {
        first start;
        then assign led1 := true;
        then assign led2 := false;
      }
      then if phase_ms >= 10000 and phase_ms < 15000 {
        first start;
        then assign led1 := false;
        then assign led2 := false;
      }
    }
    out attribute io_0 : Boolean = led1;
    out attribute io_1 : Boolean = led2;
  }
  part system : Controller;
}
